public class Repro {
  public static void main(String[] args) throws Exception {
    int latPoint = Integer.MAX_VALUE - 2;
    int lonPoint = Integer.MAX_VALUE - 2;
    double pointLat = decodeLatitude(latPoint);
    double pointLon = decodeLongitude(lonPoint);

    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);

    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});

    Component2D c2d = LatLonGeometry.create(poly);
    System.out.println("poly bbox: lat[" + poly.minLat + "," + poly.maxLat + "] lon[" + poly.minLon + "," + poly.maxLon + "]");
    System.out.println("point: " + pointLat + ", " + pointLon);
    System.out.println("Polygon2D.contains(point) = " + c2d.contains(pointLon, pointLat));

    GeoEncodingUtils.Component2DPredicate pred = GeoEncodingUtils.createComponentPredicate(c2d);
    System.out.println("predicate.test(point) = " + pred.test(latPoint, lonPoint));

    // Relation of the cell containing the point (shift=1 grid)
    int minLatEnc = encodeLatitudeCeil(poly.minLat);
    int maxLatEnc = encodeLatitude(poly.maxLat);
    int minLonEnc = encodeLongitudeCeil(poly.minLon);
    int maxLonEnc = encodeLongitude(poly.maxLon);
    System.out.println("encoded lat range: " + minLatEnc + " .. " + maxLatEnc + "  (point=" + latPoint + ")");
    System.out.println("encoded lon range: " + minLonEnc + " .. " + maxLonEnc + "  (point=" + lonPoint + ")");
    Relation r = c2d.relate(decodeLongitude(lonPoint), decodeLongitude(lonPoint), decodeLatitude(latPoint), decodeLatitude(latPoint));
    System.out.println("relate degenerate point cell = " + r);
  }
}

