package org.apache.lucene.geo;
import org.apache.lucene.index.PointValues.Relation;
import static org.apache.lucene.geo.GeoEncodingUtils.*;

public class Repro2 {
  public static void main(String[] args) throws Exception {
    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);
    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D c2d = LatLonGeometry.create(poly);

    int minLatEnc = encodeLatitudeCeil(minLat);
    int maxLatEnc = encodeLatitude(maxLat);
    int minLonEnc = encodeLongitudeCeil(minLon);
    int maxLonEnc = encodeLongitude(maxLon);
    long minLat2 = (long) minLatEnc - Integer.MIN_VALUE;
    long maxLat2 = (long) maxLatEnc - Integer.MIN_VALUE;
    int latShift = GeoUtils.computeShift(minLat2, maxLat2);
    int latBase = (int) (minLat2 >>> latShift);
    int maxLatDelta = (int) (maxLat2 >>> latShift) - latBase + 1;
    long minLon2 = (long) minLonEnc - Integer.MIN_VALUE;
    long maxLon2 = (long) maxLonEnc - Integer.MIN_VALUE;
    int lonShift = GeoUtils.computeShift(minLon2, maxLon2);
    int lonBase = (int) (minLon2 >>> lonShift);
    int maxLonDelta = (int) (maxLon2 >>> lonShift) - lonBase + 1;
    System.out.println("latShift=" + latShift + " latBase=" + latBase + " maxLatDelta=" + maxLatDelta);
    System.out.println("lonShift=" + lonShift + " lonBase=" + lonBase + " maxLonDelta=" + maxLonDelta);
    for (int i = 0; i < maxLatDelta; ++i) {
      for (int j = 0; j < maxLonDelta; ++j) {
        final int boxMinLat = ((latBase + i) << latShift) + Integer.MIN_VALUE;
        final int boxMinLon = ((lonBase + j) << lonShift) + Integer.MIN_VALUE;
        final int boxMaxLat = boxMinLat + (1 << latShift) - 1;
        final int boxMaxLon = boxMinLon + (1 << lonShift) - 1;
        Rectangle rect = new Rectangle(
            decodeLatitude(boxMinLat), decodeLatitude(boxMaxLat),
            decodeLongitude(boxMinLon), decodeLongitude(boxMaxLon));
        Relation r = c2d.relate(rect.minLon, rect.maxLon, rect.minLat, rect.maxLat);
        System.out.println("cell lat[" + boxMinLat + "," + boxMaxLat + "] lon[" + boxMinLon + "," + boxMaxLon + "] -> " + r + "  rect=" + rect);
      }
    }
  }
}
EOF
