import org.apache.lucene.analysis.standard.StandardAnalyzer;
import org.apache.lucene.codecs.lucene95.Lucene95Codec;
import org.apache.lucene.document.*;
import org.apache.lucene.geo.*;
import org.apache.lucene.index.*;
import org.apache.lucene.search.*;
import org.apache.lucene.store.*;

import static org.apache.lucene.geo.GeoEncodingUtils.*;

public class E2E {
  static final String FIELD_NAME = "point";
  public static void main(String[] args) throws Exception {
    Directory dir = new ByteBuffersDirectory();
    IndexWriter w = new IndexWriter(dir, new IndexWriterConfig(new StandardAnalyzer()));
    Document doc = new Document();
    double lat = decodeLatitude(Integer.MAX_VALUE - 2);
    double lon = decodeLongitude(Integer.MAX_VALUE - 2);
    doc.add(new LatLonPoint(FIELD_NAME, lat, lon));
    doc.add(new LatLonDocValuesField(FIELD_NAME, lat, lon));
    w.addDocument(doc);
    w.flush();
    w.commit();
    DirectoryReader reader = DirectoryReader.open(w);
    IndexSearcher s = newSearcher(reader);

    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);
    Query query = LatLonPoint.newPolygonQuery(FIELD_NAME, new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon}));
    System.out.println("index query count = " + s.count(query));

    Query dvQuery = LatLonDocValuesField.newSlowPolygonQuery(FIELD_NAME, new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon}));
    System.out.println("docvalues query count = " + s.count(dvQuery));

    // also check points further from the pole still work (regression sanity)
    Document doc2 = new Document();
    doc2.add(new LatLonPoint(FIELD_NAME, 20.0, 30.0));
    doc2.add(new LatLonDocValuesField(FIELD_NAME, 20.0, 30.0));
    w.addDocument(doc2);
    w.commit();
    reader.close();
    DirectoryReader reader2 = DirectoryReader.open(w);
    IndexSearcher s2 = newSearcher(reader2);
    Query box = LatLonPoint.newBoxQuery(FIELD_NAME, 10, 30, 20, 40);
    System.out.println("box query count (expect 1) = " + s2.count(box));
    Query dvBox = LatLonDocValuesField.newSlowBoxQuery(FIELD_NAME, 10, 30, 20, 40);
    System.out.println("dv box query count (expect 1) = " + s2.count(dvBox));
    reader2.close();
    w.close();
    dir.close();
  }
  static IndexSearcher newSearcher(IndexReader r) { return new IndexSearcher(r); }
}
EOF
